/*
 * A208908  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A208923; see the Formula section.
 * https://oeis.org/A208908
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = coefficient of v(row_of_n, term_index_of_n) in the
 *            flattened triangle of coefficients of polynomials v(n,x)
 *            generated by u(n,x) = u(n-1,x) + 2x * v(n-1,x) v(n,x) = (x+1) *
 *            u(n-1,x) + x * v(n-1,x) + 1 with u(1,x)=1, v(1,x)=1. The
 *            triangle is taken row by row, row n has n entries (coefficien...
 * Range:     u8 n <= 25, u16 n <= 59, u32 n <= 59, u64 n <= 59, u128 n <= 59,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

static seq_t *a_values = NULL;      /* flattened triangle values */
static size_t a_len   = 0;           /* number of values stored */
static size_t a_cap   = 0;           /* allocated capacity */

static seq_t *prevU = NULL;         /* coefficients of u(n-1,x) */
static seq_t *prevV = NULL;         /* coefficients of v(n-1,x) */
static size_t prev_size = 0;        /* length of previous row */
static idx_t  last_row    = 0;       /* number of rows already processed */

/* ensure a_values has room for at least 'need' elements */
static void ensure_a_capacity(size_t need)
{
    if (a_cap < need)
    {
        size_t cap = a_cap ? a_cap * 2 : 1024;
        while (cap < need) cap *= 2;
        seq_t *tmp = (seq_t *)realloc(a_values, cap * sizeof(seq_t));
        a_values = tmp;
        a_cap = cap;
    }
}

/* a(idx_t n) computes the nth element of the flattened triangle. */
seq_t a(idx_t n)
{
    if (n == 0) return 0; /* undefined for n < 1 */

    /* one‑time initialization for the first row */
    if (a_values == NULL)
    {
        /* Row 1 */
        last_row   = 1;
        prev_size  = 1;
        prevU = (seq_t *)malloc(sizeof(seq_t));
        prevV = (seq_t *)malloc(sizeof(seq_t));
        prevU[0] = (seq_t)1;
        prevV[0] = (seq_t)1;

        a_cap   = 1024;
        a_values = (seq_t *)malloc(a_cap * sizeof(seq_t));
        a_len = 1;
        a_values[0] = (seq_t)1;
    }

    /* generate additional rows until we have at least n entries */
    while (a_len < (size_t)n)
    {
        idx_t new_row = last_row + 1;
        size_t new_size = (size_t)new_row;        /* number of coeffs in new row */

        /* allocate arrays for the new row */
        seq_t *curU = (seq_t *)malloc(new_size * sizeof(seq_t));
        seq_t *curV = (seq_t *)malloc(new_size * sizeof(seq_t));

        for (size_t j = 0; j < new_size; ++j)
        {
            /* u(new_row,x) coefficient at x^j */
            seq_t u_val = 0;
            if (j < prev_size) u_val += prevU[j];
            if (j > 0)         u_val += (seq_t)2 * prevV[j-1];
            curU[j] = u_val;

            /* v(new_row,x) coefficient at x^j */
            seq_t v_val = 0;
            /* (x+1)*u_prev contributes u_prev[j] + u_prev[j-1] */
            if (j < prev_size) v_val += prevU[j];
            if (j > 0)         v_val += prevU[j-1];
            /* + x*v_prev contributes v_prev[j-1] */
            if (j > 0)         v_val += prevV[j-1];
            /* +1 only for j==0 */
            if (j == 0)        v_val += (seq_t)1;
            curV[j] = v_val;
        }

        /* append newly computed v coefficients to the flat array */
        ensure_a_capacity(a_len + new_size);
        for (size_t j = 0; j < new_size; ++j)
            a_values[a_len + j] = curV[j];
        a_len += new_size;

        /* prepare for next iteration */
        free(prevU);
        free(prevV);
        prevU = curU;
        prevV = curV;
        prev_size = new_size;
        last_row = new_row;
    }

    return a_values[(size_t)n - 1];
}
